// Land mask: 180x90 equirectangular bitset at 2° per cell (row 0 = 90°N), base64. Built from Natural Earth 110m land.
const LAND_MASK_B64 = '';
const MASK_W = 180;
const MASK_H = 90;
const MIN_LAT = -60;

let maskBits = null;

function getMaskBits() {
  if (!maskBits) maskBits = Uint8Array.from(atob(LAND_MASK_B64), (c) => c.charCodeAt(0));
  return maskBits;
}

export function isLand(latDeg, lonDeg) {
  if (latDeg < MIN_LAT) return false;
  const col = Math.min(MASK_W - 1, Math.floor((lonDeg + 180) / 2));
  const row = Math.min(MASK_H - 1, Math.floor((90 - latDeg) / 2));
  const index = row * MASK_W + col;
  return ((getMaskBits()[index >> 3] >> (index & 7)) & 1) === 1;
}

/** Unit vector for a lat/lon where lon 0 faces +z and north is +y. */
export function latLonToVec(latDeg, lonDeg) {
  const lat = (latDeg * Math.PI) / 180;
  const lon = (lonDeg * Math.PI) / 180;
  return [Math.cos(lat) * Math.sin(lon), Math.sin(lat), Math.cos(lat) * Math.cos(lon)];
}

/** Evenly spread land points (Fibonacci sphere) as lat/lon pairs. */
export function landPoints(sampleCount) {
  const points = [];
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < sampleCount; i++) {
    const y = 1 - (2 * (i + 0.5)) / sampleCount;
    const lat = (Math.asin(y) * 180) / Math.PI;
    let lon = (((i * golden) * 180) / Math.PI) % 360;
    if (lon > 180) lon -= 360;
    if (isLand(lat, lon)) points.push([lat, lon]);
  }
  return points;
}

